import React, { useState } from 'react';

export default function OwnerOccupierSection({ onSubmit }) {
  const [formData, setFormData] = useState({
    propertyNumber: '',
    ownerName: '',
    ownerUID: '',
    ownerType: 'Private',
    occupierName: '',
    occupierUID: '',
    assessmentYear: '',
    oldAssessmentValue: '',
    oldAssessmentYear: '',
    pinCode: '',
    yearOfConstruction: '',
    mobileNumber: '',
    email: '',
  });

  const [errors, setErrors] = useState({});

  // Validation helpers
  const isDigits = (v) => /^\d+$/.test(String(v));
  const isExactlyNDigits = (v, n) => new RegExp(`^\\d{${n}}$`).test(String(v));
  const matchOwnerUid = (v) => /^(remaining|\d+)$/i.test(String(v).trim());
  const validOwnerName = (v) => /^[A-Za-z\s]+$/.test(String(v).trim());
  const validGamilEmail = (v) => /^[^\s@]+@gamil\.com$/i.test(String(v).trim());
  const validYear = (v) => /^\d{4}$/.test(String(v)) && Number(v) >= 1900 && Number(v) <= 2100;

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((s) => ({ ...s, [name]: value }));
    // validate on change (light)
    validateField(name, value);
  };

  const validateField = (name, value) => {
    let msg = '';

    switch (name) {
      case 'propertyNumber':
        if (value === '' || !isDigits(value)) msg = 'Property number must be a number.';
        break;
      case 'oldAssessmentValue':
        if (value === '' || !/^\d+(\.\d+)?$/.test(String(value))) msg = 'Old assessment value must be a number (allow decimals).';
        break;
      case 'assessmentYear':
      case 'oldAssessmentYear':
      case 'yearOfConstruction':
        if (value === '' || !validYear(value)) msg = 'Enter a valid 4-digit year (e.g. 2024).';
        break;
      case 'ownerName':
        if (value.trim() === '' || !validOwnerName(value)) msg = 'Owner name must contain letters and spaces only.';
        break;
      case 'ownerUID':
      case 'occupierUID':
        if (value.trim() === '' || !matchOwnerUid(value)) msg = 'Allowed: "remaining" or numeric UID.';
        break;
      case 'pinCode':
        if (!isExactlyNDigits(value, 6)) msg = 'Pin code must be exactly 6 digits.';
        break;
      case 'mobileNumber':
        if (!isExactlyNDigits(value, 10)) msg = 'Mobile number must be exactly 10 digits.';
        break;
      case 'email':
        if (!validGamilEmail(value)) msg = 'Email must be an @gamil.com address.';
        break;
      default:
        msg = '';
    }

    setErrors((s) => ({ ...s, [name]: msg }));
    return msg === '';
  };

  const validateAll = () => {
    const names = [
      'propertyNumber','oldAssessmentValue','assessmentYear','oldAssessmentYear',
      'ownerName','ownerUID','occupierUID','pinCode','yearOfConstruction','mobileNumber','email'
    ];
    let ok = true;
    names.forEach((n) => { if (!validateField(n, formData[n] ?? '')) ok = false; });
    return ok;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!validateAll()) {
      alert('Please fix validation errors before submitting.');
      return;
    }
    // pass validated data upstream
    if (onSubmit) onSubmit(formData);
    else console.log('submit data', formData);
  };

  // small helper to render error
  const Err = ({ name }) => errors[name] ? <div className="field-error">{errors[name]}</div> : null;

  return (
    <form onSubmit={handleSubmit}>
      <fieldset>
        <legend>Owner & Occupier Details</legend>

        <div className="form-grid-2">
          <div className="form-group">
            <label>Property Number (M)</label>
            <input
              name="propertyNumber"
              value={formData.propertyNumber}
              onChange={handleChange}
              inputMode="numeric"
              pattern="\d*"
              placeholder="e.g. 123"
              required
            />
            <Err name="propertyNumber" />
          </div>

          <div className="form-group">
            <label>Old Assessment Value</label>
            <input
              name="oldAssessmentValue"
              value={formData.oldAssessmentValue}
              onChange={handleChange}
              inputMode="decimal"
              placeholder="e.g. 12345.67"
            />
            <Err name="oldAssessmentValue" />
          </div>

          <div className="form-group">
            <label>Assessment Year (M)</label>
            <input
              name="assessmentYear"
              value={formData.assessmentYear}
              onChange={handleChange}
              type="number"
              min="1900"
              max="2100"
              step="1"
              placeholder="YYYY"
              required
            />
            <Err name="assessmentYear" />
          </div>

          <div className="form-group">
            <label>Old Assessment Year</label>
            <input
              name="oldAssessmentYear"
              value={formData.oldAssessmentYear}
              onChange={handleChange}
              type="number"
              min="1900"
              max="2100"
              step="1"
              placeholder="YYYY"
            />
            <Err name="oldAssessmentYear" />
          </div>

          <div className="form-group">
            <label>Property Owner Name (M)</label>
            <input
              name="ownerName"
              value={formData.ownerName}
              onChange={handleChange}
              required
            />
            <Err name="ownerName" />
          </div>

          <div className="form-group">
            <label>Owner UID (M)</label>
            <input
              name="ownerUID"
              value={formData.ownerUID}
              onChange={handleChange}
              placeholder='number or "remaining"'
              required
            />
            <Err name="ownerUID" />
          </div>

          <div className="form-group">
            <label>Type of Owner (M)</label>
            <select name="ownerType" value={formData.ownerType} onChange={handleChange}>
              <option>Private</option>
              <option>Public</option>
              <option>State Government</option>
              <option>Central Government</option>
              <option>Semi Government</option>
              <option>Municipal Corporation</option>
              <option>Co-opp. Society (CHS)</option>
              <option>Other</option>
            </select>
          </div>

          <div className="form-group">
            <label>Name of Occupier / Tenant (M)</label>
            <input name="occupierName" value={formData.occupierName} onChange={handleChange} />
          </div>

          <div className="form-group">
            <label>Occupier UID (M)</label>
            <input
              name="occupierUID"
              value={formData.occupierUID}
              onChange={handleChange}
              placeholder='number or "remaining"'
            />
            <Err name="occupierUID" />
          </div>

          <div className="form-group">
            <label>Pin Code</label>
            <input
              name="pinCode"
              value={formData.pinCode}
              onChange={handleChange}
              inputMode="numeric"
              pattern="\d{6}"
              placeholder="6 digits"
              maxLength={6}
            />
            <Err name="pinCode" />
          </div>

          <div className="form-group">
            <label>Year of Construction</label>
            <input
              name="yearOfConstruction"
              value={formData.yearOfConstruction}
              onChange={handleChange}
              type="number"
              min="1800"
              max="2100"
              step="1"
              placeholder="YYYY"
            />
            <Err name="yearOfConstruction" />
          </div>

          <div className="form-group">
            <label>Mobile Number</label>
            <input
              name="mobileNumber"
              value={formData.mobileNumber}
              onChange={handleChange}
              inputMode="numeric"
              placeholder="10 digits"
              maxLength={10}
            />
            <Err name="mobileNumber" />
          </div>

          <div className="form-group">
            <label>Email (only @gamil.com)</label>
            <input
              name="email"
              value={formData.email}
              onChange={handleChange}
              type="email"
              placeholder="name@gamil.com"
            />
            <Err name="email" />
          </div>
        </div>

        <div style={{ marginTop: 12 }}>
          <button type="submit">Save</button>
        </div>
      </fieldset>
    </form>
  );
}
